#!/bin/bash
# Generated by evals/graders/gen_suite.py. Runs (with --scaffold) in the run's
# empty workspace. Copies the fixture project in, without the answer key, and
# makes ~/.claude/skills/wcag22-a11y resolve inside the run's sandbox HOME so the
# skill's absolute paths work.
set -euo pipefail
case_dir="$(cd "$(dirname "$0")" && pwd -P)"
evals_dir="$(cd "$case_dir/../../.." && pwd -P)"
rsync -a --exclude "__pycache__" --exclude ".DS_Store" --exclude "answer-key.md" "$evals_dir/fixtures/larkspur/project/" ./
mkdir -p "$HOME/.claude/skills"
ln -sfn "$evals_dir/plugin/skills/wcag22-a11y" "$HOME/.claude/skills/wcag22-a11y"
